  const g = guards.sort((a,b)=>a.distance-b.distance)[0];
  const idx = g.index;
  await bot.attack(g).catch(()=>{});
  const first = Date.now(); let died=false;
  while (Date.now()-first < 40_000 && Date.now() < tEnd) {
    const s2 = sdk.getState();
    if (s2.player.hitpoints < 10) { const f=sdk.findInventoryItem(/bread/i); if (f) await bot.eatFood(f).catch(()=>{}); }
    const w2 = s2.nearbyNpcs.find(n=>n.index===idx);
    if (!w2 || (w2.hp!=null && w2.hp<=0)) { died=true; break; }
    if (!s2.player.combat.inCombat) { await bot.attack(w2??g).catch(()=>{}); }
    await new Promise(r=>setTimeout(r,350));
  }
  if (died) { kills++; sdk.say(`Bravo guard kill #${kills} lvl${g.combatLevel}`); }
}
return {kills, pos:[sdk.getState().player.worldX,sdk.getState().player.worldZ], hp: sdk.getState().player.hitpoints};
